def fizzbuzz(n: int) -> list[str]:
    if n == 0:
        return []

    if n < 0:
        raise ValueError("n must be a non-negative integer.")

    output_list = []
    for current_val in range(1, n + 1):
        divisible_by_5 = current_val % 5 == 0
        divisible_by_3 = current_val % 3 == 0

        if divisible_by_3 and divisible_by_5:
            entry = "FizzBuzz"
        elif divisible_by_5:
            entry = "Buzz"
        elif divisible_by_3:
            entry = "Fizz"
        else:
            entry = str(current_val)

        output_list.append(entry)

    return output_list
```

