def fizzbuzz(n: int) -> list[str]:
    if n < 0:
        raise ValueError("n must be a non-negative integer.")

    output_list = []

    for current_val in range(1, n + 1):
        is_div_3 = current_val % 3 == 0
        is_div_5 = current_val % 5 == 0

        if is_div_3 or is_div_5:
            if is_div_3 and is_div_5:
                output_list.append("FizzBuzz")
            elif is_div_3:
                output_list.append("Fizz")
            else:
                output_list.append("Buzz")
        else:
            output_list.append(str(current_val))

    return output_list
```

