def letter_stats(text: str) -> dict[str, int]:
    results = {'other': 0, 'digits': 0, 'consonants': 0, 'vowels': 0}
    v_chars = set("aeiouAEIOU")
    for symbol in text:
        if symbol.isspace():
            continue
        if symbol.isalpha():
            if symbol in v_chars:
                results['vowels'] += 1
            else:
                results['consonants'] += 1
        elif symbol.isdigit():
            results['digits'] += 1
        else:
            results['other'] += 1
    return results
```

