def normalize(data: list[float]) -> list[float]:
    if not data:
        return []
    upper = max(data)
    lower = min(data)
    span = upper - lower
    if span == 0.0:
        return [0.0] * len(data)
    scaled_results = []
    for val in data:
        normalized_val = (val - lower) / span
        scaled_results.append(normalized_val)
    return scaled_results
```

